<script>
  (function() {
    const root = document.documentElement;
    const tok = n => getComputedStyle(root).getPropertyValue(n).trim();

    // state
    let step = 0;
    let playing = true;
    let speed = 1.0;
    let lrStep = 0.1, lrCosine = 0.1, lrWarmup = 0.01;
    let highlightCurve = null; // 'step' | 'cosine' | 'warmup' | null

    // DOM refs
    const pathStep = document.getElementById('pathStep');
    const pathCosine = document.getElementById('pathCosine');
    const pathWarmup = document.getElementById('pathWarmup');
    const indicatorLine = document.getElementById('indicatorLine');
    const labelStep = document.getElementById('labelStep');
    const labelCosine = document.getElementById('labelCosine');
    const labelWarmup = document.getElementById('labelWarmup');
    const labelGroup = document.getElementById('labelGroup');
    const stepDisplay = document.getElementById('stepDisplay');
    const playPauseBtn = document.getElementById('playPauseBtn');
    const resetBtn = document.getElementById('resetBtn');
    const speedSlider = document.getElementById('speedSlider');
    const speedVal = document.getElementById('speedVal');

    // 坐标映射
    const X0 = 60, X1 = 660, Y0 = 20, Y1 = 280;
    const xScale = (s) => X0 + (s / 100) * (X1 - X0);
    const yScale = (lr) => Y1 - (lr / 0.2) * (Y1 - Y0);

    // 计算三条曲线在给定步数的值
    function computeLR(s) {
      const stepDecay = 0.1 * Math.pow(0.5, Math.floor(s / 20));
      const cosine = 0.1 * 0.5 * (1 + Math.cos(Math.PI * s / 100));
      const warmup = 0.1 * Math.min(1, s / 10) * Math.pow(0.5, Math.floor(s / 20));
      return { step: stepDecay, cosine, warmup };
    }

    // 生成路径 d 属性 (0..s 步)
    function buildPathData(s, type) {
      if (s < 0) s = 0;
      const points = [];
      // 至少画到当前步，但为了曲线平滑，从0开始每步取点
      const maxDraw = Math.min(s, 100);
      for (let i = 0; i <= maxDraw; i++) {
        const lr = computeLR(i);
        const val = type === 'step' ? lr.step : type === 'cosine' ? lr.cosine : lr.warmup;
        points.push([xScale(i), yScale(val)]);
      }
      if (points.length === 0) return '';
      let d = `M ${points[0][0]} ${points[0][1]}`;
      for (let i = 1; i < points.length; i++) {
        d += ` L ${points[i][0]} ${points[i][1]}`;
      }
      return d;
    }

    // 更新所有视觉元素
    function update() {
      // 计算当前步的三个lr
      const vals = computeLR(step);
      lrStep = vals.step;
      lrCosine = vals.cosine;
      lrWarmup = vals.warmup;

      // 更新路径 (画到当前步)
      pathStep.setAttribute('d', buildPathData(step, 'step'));
      pathCosine.setAttribute('d', buildPathData(step, 'cosine'));
      pathWarmup.setAttribute('d', buildPathData(step, 'warmup'));

      // 更新指示竖线
      const ix = xScale(step);
      indicatorLine.setAttribute('x1', ix);
      indicatorLine.setAttribute('x2', ix);

      // 更新数值标签 (始终显示当前步的三个值)
      labelStep.textContent = lrStep.toFixed(3);
      labelCosine.textContent = lrCosine.toFixed(3);
      labelWarmup.textContent = lrWarmup.toFixed(3);

      // 高亮逻辑: 如果有高亮曲线，调整标签位置和透明度
      if (highlightCurve) {
        let targetY = 30;
        let targetX = ix + 8;
        if (highlightCurve === 'step') {
          targetY = yScale(lrStep) - 6;
          labelStep.setAttribute('y', targetY);
          labelStep.setAttribute('x', targetX);
          labelStep.setAttribute('opacity', '1');
          labelCosine.setAttribute('opacity', '0.3');
          labelWarmup.setAttribute('opacity', '0.3');
        } else if (highlightCurve === 'cosine') {
          targetY = yScale(lrCosine) - 6;
          labelCosine.setAttribute('y', targetY);
          labelCosine.setAttribute('x', targetX);
          labelCosine.setAttribute('opacity', '1');
          labelStep.setAttribute('opacity', '0.3');
          labelWarmup.setAttribute('opacity', '0.3');
        } else if (highlightCurve === 'warmup') {
          targetY = yScale(lrWarmup) - 6;
          labelWarmup.setAttribute('y', targetY);
          labelWarmup.setAttribute('x', targetX);
          labelWarmup.setAttribute('opacity', '1');
          labelStep.setAttribute('opacity', '0.3');
          labelCosine.setAttribute('opacity', '0.3');
        }
        // 确保标签组可见
        labelGroup.setAttribute('opacity', '1');
      } else {
        // 默认显示在左上角
        labelStep.setAttribute('x', '70');
        labelStep.setAttribute('y', '30');
        labelCosine.setAttribute('x', '70');
        labelCosine.setAttribute('y', '48');
        labelWarmup.setAttribute('x', '70');
        labelWarmup.setAttribute('y', '66');
        labelStep.setAttribute('opacity', '1');
        labelCosine.setAttribute('opacity', '1');
        labelWarmup.setAttribute('opacity', '1');
        labelGroup.setAttribute('opacity', '1');
      }

      stepDisplay.textContent = step;
    }

    // 动画循环
    let lastTime = 0;
    let accumulator = 0;
    function animate(time) {
      if (playing && step < 100) {
        const dt = lastTime ? (time - lastTime) / 1000 : 0;
        const stepInterval = 0.05 / speed; // 每步间隔 (秒)
        accumulator += dt;
        while (accumulator >= stepInterval && step < 100) {
          step++;
          accumulator -= stepInterval;
        }
        if (step > 100) step = 100;
        update();
      }
      lastTime = time;
      requestAnimationFrame(animate);
    }

    // 交互: 播放暂停
    playPauseBtn.addEventListener('click', () => {
      playing = !playing;
      playPauseBtn.textContent = playing ? '⏸' : '▶';
      if (playing && step >= 100) {
        step = 0;
        update();
      }
      lastTime = 0;
      accumulator = 0;
    });

    // 重置
    resetBtn.addEventListener('click', () => {
      step = 0;
      playing = true;
      playPauseBtn.textContent = '⏸';
      highlightCurve = null;
      lastTime = 0;
      accumulator = 0;
      update();
    });

    // 速度
    speedSlider.addEventListener('input', (e) => {
      speed = parseFloat(e.target.value);
      speedVal.textContent = speed.toFixed(1);
    });

    // 点击曲线高亮 (svg内点击委托)
    const svg = document.getElementById('stage');
    svg.addEventListener('click', (e) => {
      const target = e.target.closest('.curve-path');
      if (target) {
        const curve = target.dataset.curve;
        if (highlightCurve === curve) {
          highlightCurve = null; // 取消高亮
        } else {
          highlightCurve = curve;
        }
        update();
      }
    });

    // 初始绘制
    update();
    // 启动动画
    requestAnimationFrame(animate);
  })();
</script>
